{name:'Kimi',in:0.6,out:2}
];
function cost(name, inTok, outTok){
  inTok=+inTok||0; outTok=+outTok||0; var m=null;
  for(var i=0;i<MODELS.length;i++){ if(MODELS[i].name===name){ m=MODELS[i]; break; } }
  if(!m) return null;
  return (m.in*inTok + m.out*outTok)/1e6;
}
function list(){ return MODELS.map(function(m){return m.name;}); }
var EXPORTS={MODELS:MODELS,cost:cost,list:list};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TokenCostForgePure = EXPORTS; }
